-- scripts/build07_hashes.sql  (build 07, check 5)
-- Row count and content hash of the rebuilt lanes' objects (BEAUMIER, NEWBURY):
-- 14 staging tables (STG_BEAUMIER_LOCATION_MAP from M3), each lane's
